  --bg: #fafaf7;
  --surface: #ffffff;
  --surface-2: #f3f1ec;
  --ink: #14181b;
  --ink-2: #4a5158;
  --muted: #7a8088;
  --line: #e7e3da;
  --accent: #2f6f4f;
  --accent-ink: #ffffff;
  --accent-soft: #e6f0ea;
  --warn: #b34728;
  --warn-soft: #fdecdc;

  --radius-sm: 8px;
  --radius: 14px;
  --radius-lg: 22px;

  --shadow-sm: 0 1px 2px rgba(20,24,27,.05);
  --shadow: 0 8px 24px -12px rgba(20,24,27,.18);
  --shadow-lg: 0 24px 60px -28px rgba(20,24,27,.28);

  --font-sans: "Inter", "Helvetica Neue", Arial, system-ui, sans-serif;
  --font-serif: "Newsreader", "Iowan Old Style", "Georgia", serif;

  --container: 1200px;
}

/* ---------- Reset ---------- */
*, *::before, *::after { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  font-family: var(--font-sans);
  color: var(--ink);
  background: var(--bg);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}
img, svg { display: block; max-width: 100%; }
button { font: inherit; cursor: pointer; }
a { color: inherit; }

.container { width: 100%; max-width: var(--container); margin: 0 auto; padding: 0 24px; }

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute; left: 12px; top: -100px;
  background: var(--ink); color: #fff; padding: 10px 16px;
  border-radius: var(--radius-sm);
  text-decoration: none; z-index: 1000;
  transition: top .15s ease;
}
.skip-link:focus { top: 12px; }

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
  border-radius: 4px;
}

/* ---------- Header ---------- */
.site-header {
  position: sticky; top: 0; z-index: 50;
  background: rgba(250,250,247,.85);
  backdrop-filter: saturate(160%) blur(12px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 24px;
  height: 68px;
}
.brand {
  display: inline-flex; align-items: center; gap: 10px;
  text-decoration: none; color: var(--ink);
  font-weight: 600; letter-spacing: -.01em;
}
.brand-mark { color: var(--accent); font-size: 18px; }
.brand-name { font-size: 17px; }

.primary-nav ul {
  list-style: none; padding: 0; margin: 0;
  display: flex; gap: 28px; justify-content: center;
}
.primary-nav a {
  text-decoration: none; color: var(--ink-2);
  font-size: 14.5px; font-weight: 500;
  padding: 8px 2px; position: relative;
  transition: color .15s ease;
}
.primary-nav a:hover { color: var(--ink); }
.primary-nav a::after {
  content: ""; position: absolute; left: 0; right: 0; bottom: 0;
  height: 2px; background: var(--accent);
  transform: scaleX(0); transform-origin: left;
  transition: transform .2s ease;
}
.primary-nav a:hover::after { transform: scaleX(1); }

.header-actions { display: flex; gap: 4px; align-items: center; }
.icon-btn {
  background: transparent; border: 0;
  width: 40px; height: 40px; border-radius: 999px;
  color: var(--ink); display: inline-flex; align-items: center; justify-content: center;
  position: relative;
  transition: background .15s ease;
}
.icon-btn:hover { background: var(--surface-2); }
.cart-count {
  position: absolute; top: 4px; right: 4px;
  background: var(--accent); color: #fff;
  font-size: 11px; font-weight: 600;
  min-width: 18px; height: 18px; padding: 0 5px;
  border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
  line-height: 1;
}

/* ---------- Buttons & misc ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  padding: 12px 22px; border-radius: 999px;
  font-weight: 600; font-size: 14.5px;
  text-decoration: none; border: 1px solid transparent;
  transition: transform .12s ease, background .15s ease, color .15s ease, border-color .15s ease;
  white-space: nowrap;
}
.btn:active { transform: translateY(1px); }
.btn-primary { background: var(--ink); color: #fff; }
.btn-primary:hover { background: #000; }
.btn-ghost { background: transparent; color: var(--ink); border-color: var(--ink); }
.btn-ghost:hover { background: var(--ink); color: #fff; }

.eyebrow {
  text-transform: uppercase; letter-spacing: .14em;
  font-size: 12px; font-weight: 600;
  color: var(--muted); margin: 0 0 10px;
}
.eyebrow-accent { color: var(--warn); }

.section-title {
  font-family: var(--font-serif);
  font-size: clamp(28px, 3.4vw, 40px);
  line-height: 1.12; letter-spacing: -.015em;
  margin: 0;
}
.section-header {
  display: flex; justify-content: space-between; align-items: end;
  gap: 16px; margin-bottom: 28px; flex-wrap: wrap;
}
.link-arrow {
  text-decoration: none; color: var(--ink);
  font-weight: 600; font-size: 14.5px;
  border-bottom: 1px solid currentColor; padding-bottom: 2px;
}

/* ---------- Hero ---------- */
.hero { padding: 56px 0 32px; }
.hero-inner {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: 56px;
  align-items: center;
}
.hero-copy h1 {
  font-family: var(--font-serif);
  font-size: clamp(40px, 5.2vw, 64px);
  line-height: 1.04; letter-spacing: -.02em;
  margin: 0 0 18px;
}
.hero-lede { font-size: 17px; color: var(--ink-2); max-width: 52ch; margin: 0 0 28px; }
.hero-actions { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 32px; }
.hero-meta {
  list-style: none; padding: 0; margin: 0;
  display: flex; flex-wrap: wrap; gap: 18px 28px;
  color: var(--ink-2); font-size: 14px;
}
.hero-meta li { display: inline-flex; align-items: center; gap: 8px; }
.hero-meta span { color: var(--accent); font-weight: 700; }

.hero-art {
  position: relative;
  aspect-ratio: 1 / 1;
  background: linear-gradient(135deg, #e9efe6, #d8e5d3 60%, #c9d9c2);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
}
.hero-card {
  position: absolute;
  background: #fff;
  border-radius: var(--radius);
  padding: 14px 16px 14px 14px;
  box-shadow: var(--shadow);
  display: flex; align-items: center; gap: 12px;
  font-size: 13px; font-weight: 500;
  color: var(--ink);
}
.hero-card .swatch {
  width: 44px; height: 44px; border-radius: 10px; flex-shrink: 0;
}
.swatch-1 { background: linear-gradient(135deg, #b9c9a6, #8aa978); }
.swatch-2 { background: linear-gradient(135deg, #d6a98a, #a16f4a); }
.swatch-3 { background: linear-gradient(135deg, #d8c39a, #9c7a4a); }

.hero-card-a { top: 12%; left: 8%; animation: float 6s ease-in-out infinite; }
.hero-card-b { top: 44%; right: 6%; animation: float 7s ease-in-out infinite reverse; }
.hero-card-c { bottom: 10%; left: 22%; animation: float 8s ease-in-out infinite; }

@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-8px); }
}

/* ---------- Categories ---------- */
.categories { padding: 48px 0; }
.cat-grid {
  list-style: none; padding: 0; margin: 24px 0 0;
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px;
}
.cat-card {
  display: flex; align-items: flex-end;
  aspect-ratio: 4 / 5;
  border-radius: var(--radius);
  padding: 18px; color: #fff;
  text-decoration: none;
  font-weight: 600; letter-spacing: -.01em;
  position: relative; overflow: hidden;
  transition: transform .25s ease, box-shadow .25s ease;
}
.cat-card::after {
  content: ""; position: absolute; inset: 0;
  background: linear-gradient(to top, rgba(0,0,0,.45), rgba(0,0,0,0) 55%);
}
.cat-card span { position: relative; z-index: 1; font-size: 18px; }
.cat-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.cat-1 { background: linear-gradient(135deg, #6f8b6c, #354b3b); }
.cat-2 { background: linear-gradient(135deg, #c69876, #7a4b2c); }
.cat-3 { background: linear-gradient(135deg, #a8a39a, #5a564f); }
.cat-4 { background: linear-gradient(135deg, #b3b9c8, #4a5468); }

/* ---------- Featured products ---------- */
.featured { padding: 48px 0; }
.product-grid {
  list-style: none; padding: 0; margin: 0;
  display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px;
}
.product-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex; flex-direction: column;
  transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease;
}
.product-card:hover { transform: translateY(-4px); box-shadow: var(--shadow); border-color: #d4cfc1; }
.product-media {
  aspect-ratio: 4 / 5;
  position: relative;
  background: var(--surface-2);
  overflow: hidden;
}
.product-media .visual {
  position: absolute; inset: 0;
}
.product-tag {
  position: absolute; top: 12px; left: 12px;
  background: #fff; color: var(--ink);
  font-size: 11px; font-weight: 600;
  padding: 5px 10px; border-radius: 999px;
  letter-spacing: .04em; text-transform: uppercase;
}
.product-tag.new { background: var(--ink); color: #fff; }
.product-tag.sale { background: var(--warn); color: #fff; }
.product-body { padding: 16px 16px 18px; display: flex; flex-direction: column; gap: 6px; flex: 1; }
.product-cat { font-size: 12px; color: var(--muted); text-transform: uppercase; letter-spacing: .1em; margin: 0; }
.product-name { font-size: 16px; font-weight: 600; margin: 0; letter-spacing: -.01em; }
.product-name a { text-decoration: none; }
.product-name a:hover { color: var(--accent); }
.product-foot {
  display: flex; align-items: center; justify-content: space-between;
  margin-top: auto; padding-top: 10px;
}
.product-price { font-weight: 600; font-size: 15px; }
.product-price .old { color: var(--muted); text-decoration: line-through; font-weight: 400; margin-right: 6px; }
.add-btn {
  background: var(--surface-2); border: 0;
  width: 36px; height: 36px; border-radius: 999px;
  font-size: 18px; line-height: 1;
  color: var(--ink);
  display: inline-flex; align-items: center; justify-content: center;
  transition: background .15s ease, color .15s ease;
}
.add-btn:hover { background: var(--ink); color: #fff; }

/* Product visuals (CSS-only artwork) */
.v1 { background: radial-gradient(circle at 30% 30%, #e7d8b8, #b78f5e 70%); }
.v1::after { content:""; position:absolute; inset:25% 30%; background:#fff; border-radius:50%; opacity:.18;}
.v2 { background: linear-gradient(160deg, #cfd9c2, #6f8b6c); }
.v2::after { content:""; position:absolute; left:30%; right:30%; top:25%; bottom:10%; border-radius:8px 8px 60px 60px; background: rgba(255,255,255,.25);}
.v3 { background: linear-gradient(160deg, #e8dec7, #b89968); }
.v3::after { content:""; position:absolute; left:20%; right:20%; top:40%; height:35%; background: rgba(255,255,255,.18); border-radius:6px;}
.v4 { background: linear-gradient(160deg, #d6cfc2, #7a6b53); }
.v4::after { content:""; position:absolute; left:50%; top:30%; width:30%; height:50%; background:rgba(255,255,255,.2); border-radius:50% 50% 20% 20%;}
.v5 { background: linear-gradient(160deg, #b6c1d2, #4a5468); }
.v5::after { content:""; position:absolute; inset:35% 35% 25% 35%; background: rgba(255,255,255,.22); border-radius:6px;}
.v6 { background: linear-gradient(160deg, #d9a98a, #8d4f30); }
.v6::after { content:""; position:absolute; inset:30% 25%; background:rgba(255,255,255,.18); border-radius:50%;}
.v7 { background: linear-gradient(160deg, #c4cfb6, #5e7355); }
.v7::after { content:""; position:absolute; left:25%; right:25%; top:25%; bottom:25%; background:rgba(255,255,255,.2); border-radius:50% 50% 10% 10%;}
.v8 { background: linear-gradient(160deg, #ebd9bd, #c08a4e); }
.v8::after { content:""; position:absolute; inset:30% 35% 30% 35%; background:rgba(255,255,255,.22); border-radius:50%;}

/* ---------- Deals ---------- */
.deals { padding: 56px 0; background: var(--surface-2); }
.deals-timer {
  margin: 0; font-variant-numeric: tabular-nums;
  background: #fff; border: 1px solid var(--line);
  padding: 10px 16px; border-radius: 999px;
  font-size: 14px; color: var(--ink);
}
.deals-timer time { font-weight: 600; margin-left: 4px; }
.deals-grid {
  display: grid;
  grid-template-columns: 1.1fr 1fr;
  gap: 24px;
}
.deal-feature {
  background: linear-gradient(135deg, #2f6f4f, #1f4e36);
  color: #fff;
  border-radius: var(--radius-lg);
  overflow: hidden;
  position: relative;
  display: flex; flex-direction: column;
  min-height: 360px;
}
.deal-feature-art { position: absolute; inset: 0; }
.bubble { position: absolute; border-radius: 50%; opacity: .3; filter: blur(2px); }
.b1 { width: 220px; height: 220px; right: -40px; top: -40px; background: #a7d2b9; }
.b2 { width: 140px; height: 140px; right: 80px; bottom: -30px; background: #f3d4a6; }
.b3 { width: 90px; height: 90px; left: 60%; top: 35%; background: #d8c39a; }
.deal-feature-body {
  position: relative; z-index: 1;
  padding: 32px; margin-top: auto;
  max-width: 32ch;
}
.badge {
  display: inline-block; padding: 5px 10px;
  border-radius: 999px; font-size: 12px; font-weight: 600;
  letter-spacing: .04em; text-transform: uppercase;
}
.badge-sale { background: var(--warn-soft); color: var(--warn); }
.deal-feature h3 {
  font-family: var(--font-serif);
  font-size: 32px; line-height: 1.15;
  margin: 12px 0 10px;
}
.deal-feature p { color: rgba(255,255,255,.85); margin: 0 0 20px; }
.deal-feature .btn-primary { background: #fff; color: var(--ink); }
.deal-feature .btn-primary:hover { background: var(--accent-soft); color: var(--ink); }

.deal-list {
  list-style: none; padding: 0; margin: 0;
  display: grid; gap: 14px;
}
.deal-card {
  display: grid; grid-template-columns: 96px 1fr auto;
  gap: 16px; align-items: center;
  background: #fff; border: 1px solid var(--line);
  border-radius: var(--radius); padding: 12px;
  transition: border-color .15s ease, box-shadow .15s ease;
}
.deal-card:hover { border-color: #d4cfc1; box-shadow: var(--shadow-sm); }
.deal-thumb {
  width: 96px; height: 96px; border-radius: 10px;
  position: relative; overflow: hidden;
}
.deal-meta { min-width: 0; }
.deal-cat { font-size: 11px; color: var(--muted); text-transform: uppercase; letter-spacing: .1em; margin: 0 0 4px; }
.deal-name { font-size: 15px; font-weight: 600; margin: 0 0 6px; letter-spacing: -.01em; }
.deal-price { font-size: 14px; font-weight: 600; margin: 0; }
.deal-price .old { color: var(--muted); text-decoration: line-through; font-weight: 400; margin-right: 6px; }
.deal-discount {
  background: var(--warn-soft); color: var(--warn);
  font-size: 12px; font-weight: 700;
  padding: 6px 10px; border-radius: 999px;
}

/* ---------- Editorial ---------- */
.editorial { padding: 64px 0; }
.editorial-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  gap: 24px;
}
.editorial-card {
  background: #fff; border: 1px solid var(--line);
  border-radius: var(--radius); overflow: hidden;
  display: flex; flex-direction: column;
  transition: transform .2s ease, box-shadow .2s ease;
}
.editorial-card:hover { transform: translateY(-4px); box-shadow: var(--shadow); }
.ed-media {
  display: block;
  aspect-ratio: 4 / 3;
  position: relative;
}
.editorial-lead .ed-media { aspect-ratio: 4 / 3.6; }
.ed-media-1 { background: linear-gradient(135deg, #e6dcc6, #b89968 60%, #8a6f49); }
.ed-media-2 { background: linear-gradient(135deg, #d3dcc7, #6f8b6c); }
.ed-media-3 { background: linear-gradient(135deg, #ead7c8, #c08a6a); }
.ed-body { padding: 22px; display: flex; flex-direction: column; gap: 8px; flex: 1; }
.ed-meta { font-size: 13px; color: var(--muted); margin: 0; }
.tag {
  background: var(--accent-soft); color: var(--accent);
  font-weight: 600; padding: 2px 8px; border-radius: 999px;
  font-size: 11px; text-transform: uppercase; letter-spacing: .06em;
}
.editorial-card h3 {
  font-family: var(--font-serif);
  font-size: 22px; line-height: 1.2;
  letter-spacing: -.01em; margin: 4px 0 0;
}
.editorial-lead h3 { font-size: 28px; }
.editorial-card h3 a { text-decoration: none; }
.editorial-card h3 a:hover { color: var(--accent); }
.editorial-card p { color: var(--ink-2); margin: 0; }

/* ---------- Newsletter ---------- */
.newsletter {
  padding: 64px 0;
  background: var(--ink); color: #fff;
}
.news-inner {
  display: grid; grid-template-columns: 1fr 1fr;
  gap: 40px; align-items: center;
}
.newsletter h2 {
  font-family: var(--font-serif);
  font-size: clamp(28px, 3.2vw, 40px);
  line-height: 1.1; letter-spacing: -.02em; margin: 0 0 10px;
}
.newsletter p { color: rgba(255,255,255,.75); margin: 0; max-width: 50ch; }
.news-form { display: grid; grid-template-columns: 1fr auto; gap: 10px; }
.news-form input {
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.18);
  color: #fff; padding: 14px 18px;
  border-radius: 999px; font-size: 15px;
  outline: 0; min-width: 0;
}
.news-form input::placeholder { color: rgba(255,255,255,.5); }
.news-form input:focus { border-color: #fff; background: rgba(255,255,255,.12); }
.news-form .btn-primary { background: #fff; color: var(--ink); }
.news-form .btn-primary:hover { background: var(--accent-soft); }
.form-status {
  grid-column: 1 / -1;
  margin: 4px 0 0; font-size: 13.5px; min-height: 1.2em;
  color: rgba(255,255,255,.8);
}
.form-status.error { color: #ffb7a3; }
.form-status.success { color: #aedcb9; }

/* ---------- Footer ---------- */
.site-footer { background: #fff; border-top: 1px solid var(--line); padding: 56px 0 24px; }
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(3, 1fr);
  gap: 32px;
}
.footer-brand p { color: var(--ink-2); margin-top: 12px; max-width: 32ch; }
.site-footer h2 {
  font-size: 13px; text-transform: uppercase; letter-spacing: .12em;
  color: var(--muted); margin: 0 0 14px; font-weight: 600;
}
.site-footer ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 8px; }
.site-footer a { text-decoration: none; color: var(--ink-2); font-size: 14.5px; }
.site-footer a:hover { color: var(--ink); }
.footer-bottom {
  display: flex; justify-content: space-between; gap: 16px;
  padding-top: 32px; margin-top: 40px;
  border-top: 1px solid var(--line);
  color: var(--muted); font-size: 13px;
}
.footer-bottom p { margin: 0; }

/* ---------- Toast ---------- */
.toast {
  position: fixed; left: 50%; bottom: 28px;
  transform: translateX(-50%) translateY(20px);
  background: var(--ink); color: #fff;
  padding: 12px 18px; border-radius: 999px;
  font-size: 14px; font-weight: 500;
  box-shadow: var(--shadow-lg);
  opacity: 0; pointer-events: none;
  transition: opacity .2s ease, transform .2s ease;
  z-index: 100;
}
.toast.show {
  opacity: 1; transform: translateX(-50%) translateY(0);
}

/* ---------- Responsive ---------- */
@media (max-width: 980px) {
  .hero { padding: 32px 0; }
  .hero-inner { grid-template-columns: 1fr; gap: 32px; }
  .hero-art { max-width: 520px; }
  .product-grid { grid-template-columns: repeat(2, 1fr); }
  .cat-grid { grid-template-columns: repeat(2, 1fr); }
  .deals-grid { grid-template-columns: 1fr; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-lead { grid-column: 1 / -1; }
  .news-inner { grid-template-columns: 1fr; gap: 20px; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .primary-nav { display: none; }
  .header-inner { grid-template-columns: auto 1fr auto; }
}
@media (max-width: 560px) {
  .container { padding: 0 18px; }
  .product-grid { grid-template-columns: 1fr 1fr; gap: 14px; }
  .editorial-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .news-form { grid-template-columns: 1fr; }
  .news-form .btn-primary { width: 100%; }
  .deals-timer { font-size: 13px; }
  .section-header { align-items: start; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: .001ms !important;
    transition-duration: .001ms !important;
  }
}

