+      status.textContent = `Thanks — we sent a confirmation to ${email}.`;
+      status.className = 'form-status success';
+      form.reset();
+    });
+  }
+
+  // Deals countdown — ends at next midnight UTC for stability
+  const timerEl = document.getElementById('dealsTimer');
+  if (timerEl) {
+    const end = new Date();
+    end.setHours(23, 59, 59, 0);
+    function tick() {
+      const now = new Date();
+      let diff = Math.max(0, Math.floor((end - now) / 1000));
+      const h = String(Math.floor(diff / 3600)).padStart(2, '0');
+      diff %= 3600;
+      const m = String(Math.floor(diff / 60)).padStart(2, '0');
+      const s = String(diff % 60).padStart(2, '0');
+      timerEl.textContent = `${h}:${m}:${s}`;
+      timerEl.setAttribute('datetime', `PT${h}H${m}M${s}S`);
+    }
+    tick();
+    setInterval(tick, 1000);
+  }
+
